package io.mosip.testrig.apirig.coverage;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import io.mosip.testrig.apirig.coverage.MatrixFile.Row;

/**
 * The generated, read-only views of a module's matrix — never edited by hand, regenerated by {@code sync}
 * / {@code rollup}, and checked for freshness by {@code check} ({@code reports-stale}):
 * <ul>
 * <li>{@code Summary.md} — coverage dashboard;</li>
 * <li>{@code coverage.csv} — every row of every matrix file in one table, for Excel / GitHub's CSV viewer;</li>
 * <li>{@code coverage.html} — the same rows as a self-contained, offline page with filters (status, category,
 * positive/negative, endpoint file, per-row story, planned), free-text search, sorting and "download filtered as CSV".</li>
 * </ul>
 * Output is deterministic (no wall-clock time), so an unchanged matrix yields byte-identical files.
 */
final class Reports {

	static final String SUMMARY = "Summary.md";
	static final String CSV = "coverage.csv";
	static final String HTML = "coverage.html";

	private static final Pattern CODE = Pattern.compile("\\b(?:[A-Z]{2,}[-_])+[A-Z0-9]*\\d{2,}\\b");
	private static final Pattern NEGATIVE_HINT = Pattern.compile("(?i)HTTP [45]\\d\\d|\\brejected\\b|\\bfails?\\b|not[- ]found");
	private static final Pattern LEGACY = Pattern.compile("Legacy:\\s*(.+?)\\.(?=\\s|$)");
	private static final String[] CSV_HEADER = { "Module", "File", "Endpoint", "ID", "Category", "Positive/Negative",
			"Status", "Scenario", "Steps", "Expected result", "Automated test", "Story", "Legacy IDs", "Planned endpoint",
			"Notes", "Line" };

	private Reports() {
	}

	/** One matrix row, flattened for the CSV/HTML views. */
	static final class Flat {
		String module, file, subject, endpoint, id, category, polarity, status, statusKey, scenario, steps, expected, test,
				story, legacy, planned, notes;
		int line;
	}

	/** file name -> content, for every generated view. */
	static Map<String, String> render(Estate estate) {
		List<Estate.Loaded> files = new ArrayList<>();
		for (Estate.Loaded lf : estate.files.values())
			if (lf.matrix != null)
				files.add(lf);
		Map<String, String> out = new LinkedHashMap<>();
		out.put(SUMMARY, summary(files));
		List<Flat> rows = flatten(estate.inventory.moduleCode, files);
		String asOf = asOf(files);
		out.put(CSV, csv(rows));
		out.put(HTML, html(estate.inventory.moduleCode, asOf, files.size(), rows));
		return out;
	}

	private static String asOf(List<Estate.Loaded> files) {
		String asOf = "";
		for (Estate.Loaded lf : files)
			if (lf.matrix.lastUpdated != null && lf.matrix.lastUpdated.compareTo(asOf) > 0)
				asOf = lf.matrix.lastUpdated;
		return asOf;
	}

	// ---------------------------------------------------------------- rows

	static List<Flat> flatten(String module, List<Estate.Loaded> files) {
		List<Flat> out = new ArrayList<>();
		for (Estate.Loaded lf : files) {
			MatrixFile m = lf.matrix;
			String subject = lf.relPath.substring(lf.relPath.lastIndexOf('/') + 1).replaceFirst("\\.md$", "");
			for (Row r : m.rows) {
				Flat f = new Flat();
				f.module = module;
				f.file = lf.relPath;
				f.subject = subject;
				f.endpoint = endpointOf(r, m.units);
				f.id = clean(r.id());
				f.category = r.type();
				f.status = statusLabel(r);
				f.statusKey = r.status() == MatrixFile.Status.AUTOMATED ? "auto"
						: r.status() == MatrixFile.Status.NOT_AUTOMATABLE ? "na" : "todo";
				f.polarity = polarity(r);
				f.scenario = clean(r.scenario());
				f.steps = clean(String.join("\n", r.stepList()));
				f.expected = clean(r.expected());
				f.test = String.join(", ", r.testRefs());
				f.story = clean(r.story());
				f.legacy = legacyIds(r.notes());
				f.planned = m.planned ? "yes" : "";
				f.notes = clean(r.notes());
				f.line = r.line();
				out.add(f);
			}
		}
		return out;
	}

	private static String endpointOf(Row r, List<String> units) {
		if (units.size() == 1)
			return units.get(0);
		String best = "";
		for (String u : units)
			if (r.scenario().contains(u) && u.length() > best.length())
				best = u;
		return best;
	}

	private static String statusLabel(Row r) {
		switch (r.status()) {
		case AUTOMATED:
			return "Automated";
		case NOT_AUTOMATED:
			return "Not automated";
		case NOT_AUTOMATABLE:
			return "Not automatable";
		default:
			return "Unknown";
		}
	}

	/**
	 * Positive (success path) or Negative (the call should be rejected). Exact for categories that only go one
	 * way; for boundary / idempotency / data-isolation / dependency rows it is read from the expected result
	 * (an error code, a 4xx/5xx, "rejected", "fails", "not found" → Negative).
	 */
	static String polarity(Row r) {
		if (r.status() == MatrixFile.Status.NOT_AUTOMATABLE)
			return "";
		switch (r.type()) {
		case "positive":
		case "multilang":
			return "Positive";
		case "validation":
		case "not_found":
		case "authn":
		case "authz":
			return "Negative";
		default:
			String e = r.expected();
			return CODE.matcher(e).find() || NEGATIVE_HINT.matcher(e).find() ? "Negative" : "Positive";
		}
	}

	static String legacyIds(String notes) {
		List<String> ids = new ArrayList<>();
		Matcher m = LEGACY.matcher(notes);
		while (m.find())
			for (String id : m.group(1).split(","))
				if (!id.isBlank())
					ids.add(id.trim());
		return String.join(", ", ids);
	}

	private static String clean(String s) {
		return s == null ? "" : s.replace("\\|", "|");
	}

	// ---------------------------------------------------------------- Summary.md

	static String summary(List<Estate.Loaded> files) {
		List<MatrixFile> mfs = new ArrayList<>();
		for (Estate.Loaded lf : files)
			mfs.add(lf.matrix);
		mfs.sort(Comparator.comparing(m -> m.subjectCode == null ? "" : m.subjectCode));

		String asOf = asOf(files);
		int[] total = new int[4];
		Map<String, int[]> byCategory = new LinkedHashMap<>();
		Set<String> categories = new LinkedHashSet<>();
		for (MatrixFile m : mfs) {
			int[] c = m.countStatuses();
			for (int i = 0; i < 4; i++)
				total[i] += c[i];
			for (Row r : m.rows) {
				categories.add(r.type());
				int[] bc = byCategory.computeIfAbsent(r.type(), k -> new int[3]);
				switch (r.status()) {
				case AUTOMATED:
					bc[0]++;
					break;
				case NOT_AUTOMATED:
					bc[1]++;
					break;
				case NOT_AUTOMATABLE:
					bc[2]++;
					break;
				default:
					break;
				}
			}
		}

		StringBuilder b = new StringBuilder();
		b.append("# Coverage Summary\n\n");
		b.append("As of: ").append(asOf).append("\n\n");
		b.append("To filter or sort individual test cases across every file, open `coverage.html` in a browser (or "
				+ "`coverage.csv` in Excel). Both are generated from the matrix files — don't edit them.\n\n");
		b.append("## Estate totals\n\n");
		b.append("| Total | ✅ Automated | 🟡 Not automated | ⛔ Not automatable | Coverage |\n|---|---|---|---|---|\n");
		b.append("| ").append(total[0]).append(" | ").append(total[1]).append(" | ").append(total[2]).append(" | ")
				.append(total[3]).append(" | ").append(MatrixFile.percent(total[1], total[2])).append(" |\n\n");
		b.append("## By subject\n\n");
		b.append("| Subject | Automated | Total scenarios | Coverage |\n|---|---|---|---|\n");
		for (MatrixFile m : mfs) {
			int[] c = m.countStatuses();
			b.append("| `").append(m.subjectCode).append("` | ").append(c[1]).append('/').append(c[1] + c[2])
					.append(" | ").append(c[0]).append(" | ").append(MatrixFile.percent(c[1], c[2])).append(" |\n");
		}
		b.append("\n## By category\n\n");
		b.append("| Category | ✅ Automated | 🟡 Not automated | ⛔ Not automatable | Coverage |\n|---|---|---|---|---|\n");
		List<String> cats = new ArrayList<>(categories);
		cats.sort(Comparator.comparingInt(CategoryChecklist::order));
		for (String cat : cats) {
			int[] bc = byCategory.get(cat);
			b.append("| `").append(cat).append("` | ").append(bc[0]).append(" | ").append(bc[1]).append(" | ")
					.append(bc[2]).append(" | ").append(MatrixFile.percent(bc[0], bc[1])).append(" |\n");
		}
		b.append("\n## Flagged findings\n\n");
		b.append("Rows whose Notes are flagged ⚠️ (fragility/quality concern) or 🛑 (confirmed bug) during the cycle-2 "
				+ "semantic audit (see the module's AGENTS.md, cycle 2). Pulled "
				+ "mechanically from row Notes, not hand-maintained here.\n\n");
		for (MatrixFile m : mfs)
			for (Row r : m.rows) {
				String notes = r.notes();
				if (notes.contains("🛑") || notes.contains("⚠️"))
					b.append("- ").append(notes.contains("🛑") ? "🛑" : "⚠️").append(" **").append(m.subject)
							.append("** (`").append(r.id()).append("`): ").append(notes).append('\n');
			}
		b.append('\n');
		return b.toString();
	}

	// ---------------------------------------------------------------- coverage.csv

	static String csv(List<Flat> rows) {
		StringBuilder b = new StringBuilder("﻿"); // BOM, so Excel reads UTF-8 correctly
		b.append(csvLine(CSV_HEADER));
		for (Flat f : rows)
			b.append(csvLine(new String[] { f.module, f.file, f.endpoint, f.id, f.category, f.polarity, f.status,
					f.scenario, f.steps, f.expected, f.test, f.story, f.legacy, f.planned, f.notes, String.valueOf(f.line) }));
		return b.toString();
	}

	private static String csvLine(String[] cells) {
		StringBuilder b = new StringBuilder();
		for (int i = 0; i < cells.length; i++) {
			if (i > 0)
				b.append(',');
			b.append('"').append(cells[i] == null ? "" : cells[i].replace("\"", "\"\"")).append('"');
		}
		return b.append('\n').toString();
	}

	// ---------------------------------------------------------------- coverage.html

	static String html(String module, String asOf, int fileCount, List<Flat> rows) {
		StringBuilder data = new StringBuilder("[\n");
		for (int i = 0; i < rows.size(); i++) {
			Flat f = rows.get(i);
			data.append('{');
			field(data, "file", f.file, true);
			field(data, "subject", f.subject, false);
			field(data, "endpoint", f.endpoint, false);
			field(data, "id", f.id, false);
			field(data, "category", f.category, false);
			field(data, "polarity", f.polarity, false);
			field(data, "status", f.status, false);
			field(data, "statusKey", f.statusKey, false);
			field(data, "scenario", f.scenario, false);
			field(data, "steps", f.steps, false);
			field(data, "expected", f.expected, false);
			field(data, "test", f.test, false);
			field(data, "story", f.story, false);
			field(data, "legacy", f.legacy, false);
			field(data, "planned", f.planned, false);
			field(data, "notes", f.notes, false);
			data.append(",\"line\":").append(f.line).append('}').append(i + 1 < rows.size() ? ",\n" : "\n");
		}
		data.append(']');
		String title = module + " test cases";
		String sub = "Generated from the coverage matrix (" + fileCount + " .md files) by CoverageCli — read-only, "
				+ "regenerated on every sync; edit the .md files, never this page. As of " + asOf + ".";
		return HTML_TEMPLATE.replace("{{TITLE}}", escHtml(title)).replace("{{SUB}}", escHtml(sub))
				.replace("{{DATA}}", data.toString());
	}

	private static void field(StringBuilder b, String k, String v, boolean first) {
		if (!first)
			b.append(',');
		b.append('"').append(k).append("\":").append(json(v));
	}

	/** JSON string literal that is also safe inside a script element (no "</"). */
	static String json(String s) {
		StringBuilder b = new StringBuilder("\"");
		for (char c : (s == null ? "" : s).toCharArray()) {
			switch (c) {
			case '"':
				b.append("\\\"");
				break;
			case '\\':
				b.append("\\\\");
				break;
			case '<':
				b.append("\\u003c");
				break;
			case '>':
				b.append("\\u003e");
				break;
			case '&':
				b.append("\\u0026");
				break;
			case '\n':
				b.append("\\n");
				break;
			case '\r':
				b.append("\\r");
				break;
			case '\t':
				b.append("\\t");
				break;
			default:
				if (c < 0x20)
					b.append(String.format(Locale.ROOT, "\\u%04x", (int) c));
				else
					b.append(c);
			}
		}
		return b.append('"').toString();
	}

	private static String escHtml(String s) {
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
	}

	/* The page is plain HTML/CSS/JS with no external resources, so it works offline and from a file:// URL.
	   The script deliberately contains no backslashes (Java text-block escaping). */
	private static final String HTML_TEMPLATE = """
			<!doctype html>
			<html lang="en">
			<head>
			<meta charset="utf-8">
			<meta name="viewport" content="width=device-width, initial-scale=1">
			<title>{{TITLE}}</title>
			<style>
			:root { --bg:#fff; --fg:#1f2328; --muted:#59636e; --line:#d1d9e0; --head:#f6f8fa; --code:#eff1f3;
			  --auto:#1a7f37; --auto-bg:#dafbe1; --todo:#9a6700; --todo-bg:#fff8c5; --na:#59636e; --na-bg:#eaeef2; --accent:#0969da; }
			@media (prefers-color-scheme: dark) { :root { --bg:#0d1117; --fg:#e6edf3; --muted:#9198a1; --line:#3d444d; --head:#151b23;
			  --code:#262c36; --auto:#3fb950; --auto-bg:#12261e; --todo:#d29922; --todo-bg:#272115; --na:#9198a1; --na-bg:#212830; --accent:#4493f8; } }
			* { box-sizing:border-box; }
			body { margin:0; padding:16px; background:var(--bg); color:var(--fg); font:14px/1.45 -apple-system,"Segoe UI",Roboto,Arial,sans-serif; }
			h1 { font-size:20px; margin:0 0 4px; }
			.sub { color:var(--muted); margin:0 0 14px; font-size:13px; }
			.filters { display:flex; flex-wrap:wrap; gap:8px; align-items:flex-end; margin-bottom:10px; }
			.filters label { display:flex; flex-direction:column; font-size:12px; color:var(--muted); gap:3px; }
			.filters select, .filters input { font:inherit; color:var(--fg); background:var(--bg); border:1px solid var(--line);
			  border-radius:6px; padding:5px 8px; min-width:140px; }
			.filters input { min-width:240px; }
			button { font:inherit; color:var(--fg); background:var(--head); border:1px solid var(--line); border-radius:6px;
			  padding:5px 12px; cursor:pointer; }
			button:hover { border-color:var(--accent); }
			.bar { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin:6px 0 10px; font-size:13px; }
			.chip { border-radius:999px; padding:2px 10px; font-size:12px; white-space:nowrap; }
			.auto { color:var(--auto); background:var(--auto-bg); } .todo { color:var(--todo); background:var(--todo-bg); }
			.na { color:var(--na); background:var(--na-bg); }
			.wrap { overflow-x:auto; border:1px solid var(--line); border-radius:8px; }
			table { border-collapse:collapse; width:100%; min-width:1100px; }
			th, td { text-align:left; vertical-align:top; padding:6px 8px; border-bottom:1px solid var(--line); }
			th { position:sticky; top:0; background:var(--head); font-size:12px; cursor:pointer; user-select:none; white-space:nowrap; }
			th[aria-sort="ascending"]::after { content:" ▲"; } th[aria-sort="descending"]::after { content:" ▼"; }
			td.id { font-family:ui-monospace,Consolas,monospace; font-size:12px; white-space:nowrap; }
			td.small, td.ep { font-size:12px; color:var(--muted); }
			td.steps { min-width:260px; } td.steps ol { margin:0; padding-left:18px; } td.steps li { margin:0 0 2px; }
			td.ep code { color:var(--fg); }
			code { background:var(--code); border-radius:4px; padding:0 3px; font-size:12px; font-family:ui-monospace,Consolas,monospace; }
			a { color:var(--accent); text-decoration:none; } a:hover { text-decoration:underline; }
			details summary { cursor:pointer; color:var(--accent); font-size:12px; }
			.empty { padding:24px; text-align:center; color:var(--muted); }
			@media (max-width:640px) { body { padding:16px; } .filters label, .filters select, .filters input { width:100%; min-width:0; } }
			</style>
			</head>
			<body>
			<h1>{{TITLE}}</h1>
			<p class="sub">{{SUB}}</p>
			<div class="filters">
			  <label>Search<input id="f-q" type="search" placeholder="ID, error code, story, legacy ID, words..."></label>
			  <label>Status<select id="f-status"><option value="">All</option></select></label>
			  <label>Category<select id="f-category"><option value="">All</option></select></label>
			  <label>Positive / negative<select id="f-polarity"><option value="">All</option></select></label>
			  <label>Endpoint file<select id="f-subject"><option value="">All</option></select></label>
			  <label>Story<select id="f-story"><option value="">All</option></select></label>
			  <label>Endpoint has a test?<select id="f-planned"><option value="">All</option>
			    <option value="wired">Yes (automated subject)</option><option value="planned">No (planned endpoint)</option></select></label>
			  <button id="reset" type="button">Reset</button>
			  <button id="download" type="button">Download filtered CSV</button>
			</div>
			<div class="bar" id="bar"></div>
			<div class="wrap"><table>
			<thead><tr id="head"></tr></thead>
			<tbody id="body"></tbody>
			</table></div>
			<script id="data" type="application/json">{{DATA}}</script>
			<script>
			(function () {
			  var DATA = JSON.parse(document.getElementById("data").textContent);
			  var COLS = [["id","ID"],["subject","Endpoint file"],["category","Category"],["polarity","+/-"],["status","Status"],
			    ["scenario","Scenario (given/when)"],["steps","Steps"],["expected","Expected result (then)"],["story","Story"],["legacy","Legacy IDs"],["notes","Notes"]];
			  var KEYS = ["q","status","category","polarity","subject","story","planned"];
			  var F = {}; var sortKey = ""; var sortDir = 1;
			  function el(id) { return document.getElementById(id); }
			  function esc(s) { return String(s == null ? "" : s).split("&").join("&amp;").split("<").join("&lt;").split(">").join("&gt;").split('"').join("&quot;"); }
			  function md(s) { var parts = esc(s).split("**").join("").split("`"); var out = "";
			    for (var i = 0; i < parts.length; i++) out += (i % 2 === 1 && i < parts.length - 1) ? "<code>" + parts[i] + "</code>" : (i % 2 === 1 ? "`" + parts[i] : parts[i]);
			    return out; }
			  function steps(s) { if (!s) return ""; var nl = String.fromCharCode(10);
			    return "<ol>" + s.split(nl).map(function (x) { var y = x.replace(/^[0-9]+[.)] */, "");
			      return "<li>" + md(y) + "</li>"; }).join("") + "</ol>"; }
			  function uniq(key, split) { var set = {}; DATA.forEach(function (r) {
			    (split ? (r[key] ? r[key].split(", ") : []) : [r[key]]).forEach(function (v) { if (v) set[v] = 1; }); });
			    return Object.keys(set).sort(); }
			  function fill(id, values) { var s = el("f-" + id); values.forEach(function (v) {
			    var o = document.createElement("option"); o.value = v; o.textContent = v; s.appendChild(o); }); }
			  fill("status", ["Automated", "Not automated", "Not automatable"]);
			  fill("category", uniq("category"));
			  fill("polarity", ["Positive", "Negative"]);
			  fill("subject", uniq("subject"));
			  fill("story", uniq("story", true));
			  function matches(r) {
			    if (F.status && r.status !== F.status) return false;
			    if (F.category && r.category !== F.category) return false;
			    if (F.polarity && r.polarity !== F.polarity) return false;
			    if (F.subject && r.subject !== F.subject) return false;
			    if (F.story && (", " + r.story + ", ").indexOf(", " + F.story + ", ") < 0) return false;
			    if (F.planned === "planned" && r.planned !== "yes") return false;
			    if (F.planned === "wired" && r.planned === "yes") return false;
			    if (F.q) { var hay = [r.id, r.subject, r.endpoint, r.category, r.status, r.scenario, r.steps, r.expected, r.test, r.story, r.legacy, r.notes].join(" ").toLowerCase();
			      var terms = F.q.toLowerCase().split(" ");
			      for (var i = 0; i < terms.length; i++) if (terms[i] && hay.indexOf(terms[i]) < 0) return false; }
			    return true; }
			  function current() { var list = DATA.filter(matches);
			    if (sortKey) list = list.slice().sort(function (a, b) { var x = String(a[sortKey]).toLowerCase(), y = String(b[sortKey]).toLowerCase();
			      return x < y ? -sortDir : x > y ? sortDir : 0; });
			    return list; }
			  function head() { el("head").innerHTML = COLS.map(function (c) {
			    var s = sortKey === c[0] ? (sortDir > 0 ? "ascending" : "descending") : "none";
			    return '<th data-k="' + c[0] + '" aria-sort="' + s + '">' + c[1] + "</th>"; }).join(""); }
			  function cell(r) {
			    return '<td class="id"><a href="' + esc(r.file) + '" title="' + esc(r.file) + ", line " + r.line + '">' + esc(r.id) + "</a></td>"
			      + '<td class="ep">' + esc(r.subject) + (r.endpoint ? "<br><code>" + esc(r.endpoint) + "</code>" : "") + (r.planned ? "<br>(planned)" : "") + "</td>"
			      + "<td>" + esc(r.category) + "</td><td>" + esc(r.polarity) + "</td>"
			      + '<td><span class="chip ' + r.statusKey + '">' + esc(r.status) + "</span></td>"
			      + "<td>" + md(r.scenario) + '</td><td class="steps">' + steps(r.steps) + "</td><td>" + md(r.expected) + (r.test ? '<br><span class="small">Test: ' + md("`" + r.test + "`") + "</span>" : "") + "</td>"
			      + '<td class="small">' + esc(r.story) + "</td>"
			      + '<td class="small">' + esc(r.legacy) + "</td>"
			      + '<td class="small">' + (r.notes ? "<details><summary>show</summary>" + md(r.notes) + "</details>" : "") + "</td>"; }
			  function render() {
			    var list = current();
			    el("body").innerHTML = list.length ? list.map(function (r) { return "<tr>" + cell(r) + "</tr>"; }).join("")
			      : '<tr><td colspan="' + COLS.length + '" class="empty">No test cases match these filters.</td></tr>';
			    var n = { auto: 0, todo: 0, na: 0 }; list.forEach(function (r) { n[r.statusKey]++; });
			    var cov = n.auto + n.todo ? Math.round(1000 * n.auto / (n.auto + n.todo)) / 10 + "%" : "n/a";
			    el("bar").innerHTML = "<b>" + list.length + "</b>&nbsp;of " + DATA.length + " test cases"
			      + ' <span class="chip auto">Automated ' + n.auto + '</span><span class="chip todo">Not automated ' + n.todo
			      + '</span><span class="chip na">Not automatable ' + n.na + "</span> coverage of shown rows: " + cov;
			    head(); save(); }
			  function save() { var p = []; KEYS.forEach(function (k) { if (F[k]) p.push(k + "=" + encodeURIComponent(F[k])); });
			    if (sortKey) p.push("sort=" + sortKey + (sortDir < 0 ? "-" : ""));
			    history.replaceState(null, "", p.length ? "#" + p.join("&") : location.pathname + location.search); }
			  function load() { location.hash.replace("#", "").split("&").forEach(function (kv) {
			    var i = kv.indexOf("="); if (i < 0) return; var k = kv.slice(0, i), v = decodeURIComponent(kv.slice(i + 1));
			    if (k === "sort") { sortDir = v.slice(-1) === "-" ? -1 : 1; sortKey = v.split("-").join(""); }
			    else if (KEYS.indexOf(k) >= 0) { F[k] = v; el("f-" + k).value = v; } }); }
			  KEYS.forEach(function (k) { el("f-" + k).addEventListener(k === "q" ? "input" : "change", function (e) { F[k] = e.target.value; render(); }); });
			  el("head").addEventListener("click", function (e) { var k = e.target.getAttribute("data-k"); if (!k) return;
			    if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = 1; } render(); });
			  el("reset").addEventListener("click", function () { F = {}; sortKey = ""; sortDir = 1;
			    KEYS.forEach(function (k) { el("f-" + k).value = ""; }); render(); });
			  el("download").addEventListener("click", function () {
			    var cols = ["file","endpoint","id","category","polarity","status","scenario","steps","expected","test","story","legacy","planned","notes"];
			    var nl = String.fromCharCode(10);
			    var lines = [cols.join(",")].concat(current().map(function (r) {
			      return cols.map(function (c) { return '"' + String(r[c] == null ? "" : r[c]).split('"').join('""') + '"'; }).join(","); }));
			    var blob = new Blob([String.fromCharCode(65279) + lines.join(nl) + nl], { type: "text/csv;charset=utf-8" });
			    var a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "test-cases-filtered.csv";
			    document.body.appendChild(a); a.click(); a.remove(); });
			  load(); render();
			})();
			</script>
			</body>
			</html>
			""";
}
